"""HTTP Request node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional
from urllib.parse import urljoin, urlsplit
from urllib.request import HTTPRedirectHandler, build_opener

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError


def _require_http_url(url: str, *, base: Optional[str] = None) -> None:
    try:
        scheme = urlsplit(urljoin(base, url) if base else url).scheme.lower()
    except ValueError:
        scheme = ''
    if scheme not in ('http', 'https'):
        raise NodeError('unsupported_url_scheme', 'Only http:// and https:// URLs are supported.')


class _HttpOnlyRedirects(HTTPRedirectHandler):
    def http_error_302(self, req, fp, code, msg, headers):
        # Check before urllib's redirect handler, which permits FTP and otherwise
        # converts forbidden schemes into a generic HTTP-status error.
        target = headers.get('location') or headers.get('uri')
        if target is not None:
            try:
                _require_http_url(target, base=req.full_url)
            except NodeError:
                fp.close()
                raise
        return super().http_error_302(req, fp, code, msg, headers)

    http_error_301 = http_error_303 = http_error_307 = http_error_308 = http_error_302

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        _require_http_url(newurl)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def _open_http(request, timeout):
    # A private opener keeps redirects restricted without changing urllib's
    # process-global opener or affecting other consumers.
    _require_http_url(request.full_url)
    return build_opener(_HttpOnlyRedirects()).open(request, timeout=timeout)


class HttpRequestNode(Node):
    """Make an HTTP GET or POST request and forward the response body (as text, or saved to a run-owned file)."""

    node_type: ClassVar[str] = 'http_request_node'
    display_name: ClassVar[str] = 'HTTP Request'
    default_alias: ClassVar[str] = 'HTTP Request'
    description: ClassVar[str] = 'Make an HTTP GET or POST request and forward the response body (as text, or saved to a run-owned file)'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Inputs'
    tags: ClassVar[List[str]] = ['Internet']
    icon_name: ClassVar[str] = 'globe'
    color_hint: ClassVar[str] = 'green'
    group: ClassVar[Optional[str]] = 'Web Request'
    selector_section: ClassVar[Optional[str]] = 'Web'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Response', 'description': 'The response body: text, or a file reference when Response as is file'}}
    default_config: ClassVar[Dict[str, Any]] = {'url': '', 'method': 'GET', 'body_source': 'config', 'body': '', 'response_mode': 'text', 'keep_response_file': False, 'timeout_seconds': 10.0, 'auth_token_secret': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'url': {'type': 'string', 'label': 'URL', 'placeholder': 'https://example.com/api', 'required': True, 'tab': 'Parameters'}, 'method': {'type': 'select', 'label': 'Method', 'options': ['GET', 'POST'], 'tab': 'Parameters'}, 'body_source': {'type': 'select', 'label': 'Body from (POST)', 'options': ['config', 'input'], 'description': "config sends the Request body field; input sends the node's input (text as is, anything else as JSON)", 'visible_when': {'method': 'POST'}, 'tab': 'Parameters'}, 'body': {'type': 'multiline', 'label': 'Request body (POST)', 'required': False, 'visible_when': {'method': 'POST'}, 'tab': 'Parameters'}, 'response_mode': {'type': 'select', 'label': 'Response as', 'options': ['text', 'file'], 'description': 'text decodes the body; file saves the raw bytes to a run-owned file and outputs a file reference', 'tab': 'Parameters'}, 'keep_response_file': {'type': 'boolean', 'label': 'Keep the response file after the run', 'description': 'Off: the file is deleted when the run succeeds (kept if it fails). On: always kept.', 'visible_when': {'response_mode': 'file'}, 'tab': 'Parameters'}, 'timeout_seconds': {'type': 'float', 'label': 'Timeout (seconds)', 'required': False, 'min': 0, 'min_exclusive': True, 'tab': 'Parameters'}, 'auth_token_secret': {'type': 'string', 'label': 'Bearer token (secrets store key)', 'secret': True, 'required': False, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'missing_url', 'description': 'No URL is configured.', 'retryable': False}, {'code': 'unsupported_url_scheme', 'description': 'Only http:// and https:// URLs are supported, including redirects.', 'retryable': False}, {'code': 'timeout', 'description': 'The server did not answer within the timeout.', 'retryable': True}, {'code': 'network', 'description': 'The request could not reach the server (DNS, refused, TLS...).', 'retryable': True}, {'code': 'http_status', 'description': 'The server answered with an HTTP error status (details carry status and body).', 'retryable': False}]

    @classmethod
    def describe_output_ports(cls, config: Optional[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        """C3: the response is text, or a file reference in file mode."""
        file_mode = str((config or {}).get("response_mode") or "text") == "file"
        return {"default": {"data_type": "file" if file_mode else "string"}}

    async def execute(self, context: NodeContext) -> None:
        import urllib.error
        import urllib.request

        url = str(self.config.get("url") or "").strip()
        if not url:
            context.signal_error(NodeError("missing_url", "URL is required; use http:// or https://."))
            return

        try:
            _require_http_url(url)
        except NodeError as exc:
            context.signal_error(exc)
            return

        method = str(self.config.get("method") or "GET").upper()
        timeout = float(self.config.get("timeout_seconds") or 10.0)
        file_mode = str(self.config.get("response_mode") or "text") == "file"
        if file_mode and context.run_session is None:
            context.signal_error(RuntimeError("Saving the response to a file needs a run"))
            return

        try:
            body_bytes, body_type = self._request_body(context, method)
            req = urllib.request.Request(url, data=body_bytes, method=method)
            if body_type:
                req.add_header("Content-Type", body_type)
            token_key = str(self.config.get("auth_token_secret") or "").strip()
            if token_key:
                token = context.get_secret(token_key)
                if token:
                    req.add_header("Authorization", f"Bearer {token}")
            with _open_http(req, timeout=timeout) as response:
                if file_mode:
                    result = self._save_response(context, response)
                else:
                    charset = "utf-8"
                    content_type = response.headers.get("Content-Type", "")
                    if "charset=" in content_type:
                        charset = content_type.split("charset=")[-1].split(";")[0].strip()
                    result = response.read().decode(charset, errors="replace")
            context.signal_done({"data": {"default": result}})
        except NodeError as exc:
            context.signal_error(exc)
        except urllib.error.HTTPError as exc:
            try:
                body = exc.read(4096).decode("utf-8", errors="replace")
            except Exception:
                body = ""
            context.signal_error(NodeError(
                "http_status", str(exc),
                details={"status": exc.code, "url": url, "response_body": body},
            ))
        except (urllib.error.URLError, TimeoutError) as exc:
            # Socket timeouts raise TimeoutError directly, not URLError.
            reason = getattr(exc, "reason", exc)
            code = "timeout" if isinstance(reason, TimeoutError) else "network"
            context.signal_error(NodeError(code, str(exc), details={"url": url}))

    def _request_body(self, context: NodeContext, method: str):
        """Return (body bytes or None, Content-Type or None) for the request."""
        import json

        from ...node_errors import json_safe

        if method != "POST":
            return None, None
        if str(self.config.get("body_source") or "config") == "input":
            value = context.inputs.get("input")
            if value is None:
                return b"", None
            if isinstance(value, str):
                return value.encode("utf-8"), "text/plain; charset=utf-8"
            if isinstance(value, (bytes, bytearray)):
                return bytes(value), "application/octet-stream"
            return json.dumps(json_safe(value)).encode("utf-8"), "application/json"
        text = str(self.config.get("body") or "")
        return (text.encode("utf-8") if text else None), None

    def _save_response(self, context: NodeContext, response: Any) -> Dict[str, str]:
        """Stream the raw response bytes into a run-owned file (R4)."""
        import mimetypes

        content_type = response.headers.get("Content-Type", "").split(";")[0].strip()
        extension = mimetypes.guess_extension(content_type) if content_type else None
        session = context.run_session
        path = session.new_run_file(f"{context.node_id}{extension or '.bin'}")
        with open(path, "wb") as handle:
            while True:
                chunk = response.read(65536)
                if not chunk:
                    break
                handle.write(chunk)
        if self.config.get("keep_response_file"):
            return session.keep_file(path)
        return session.run_file_reference(path)
